 return {schema:'cgp.s0c.analysis.v1',groups,baselines,ratios,decision:{productionApproved:false,productionSpeedupEstablished:false,eightReadsEstablished:false,originalReadsSkipped:0,cg0Proceed:false,cg3Proceed:false,next:'P is compared with production images, not F; delta/incremental materialization, restoring wire/transaction and the five-owner comparison remain; no production adoption'},limitations:['isolated representation object store, no owner session or live authorization','fresh full-object IO and hashing, no suffix IO or cross-call cache','new compact signature/profile is test-only; no old-reader downgrade','checkpoint/journal resync not included in timed materializer','all historical roots are retained; no physical GC or migration authorization','warm rotating order, three independent cohorts; no five-owner throughput claim','P holds neither the original wire nor the registry image transaction, so P and production images do not hold the same content','production read excludes record signature verification and includes journal and checkpoint work, so its time is not comparable with F/W/P','F/W registry closures depend on the Anchor wire for verification; only P closures verify on their own']};
